    for (int j = 0; j < grid[i].length; j++) {
      String c = grid[i][j];
      if (c == '#') row.add(0);
      else if (c == '.') row.add(1);
      else if (c == 'S') row.add(2);
      else if (c == 'D') row.add(3);
      else if (c == 'I') row.add(4);
      else if (c == 'K') row.add(5);
      else row.add(6);
    }
    board.add(row);
  }

  List<int> stack = [];
  for (int i = 0; i < commands.length; i++) {
    String cmd = commands[i];
    if (cmd == '!') {
      if (stack.isNotEmpty) stack.removeLast();
    } else if (cmd == 'S') {
      stack.add(2);
    } else if (cmd == 'D') {
      stack.add(3);
    } else if (cmd == 'I') {
      stack.add(4);
    } else if (cmd == 'K') {
      stack.add(5);
    } else if (cmd == '^') {
      if (stack.length >= 2) {
        int a = stack.removeLast();
        int b = stack.removeLast();
        stack.add(a > b ? a : b);
      }
    } else if (cmd == '<') {
      if (stack.isNotEmpty) {
        stack[stack.length - 1]--;
      }
    } else {
      stack.add(6);
    }
  }

  StringBuffer sb = StringBuffer();
  List<int> reversed = List.generate(stack.length, (i) => stack[stack.length - 1 - i]);
  for (int i = 0; i < board.length; i++) {
    for (int j = 0; j < board[i].length; j++) {
      int idx = board[i][j];
      if (idx == 0) sb.write('#');
      else if (idx == 1) sb.write('.');
      else if (idx == 2) sb.write('S');
      else if (idx == 3) sb.write('D');
      else if (idx == 4) sb.write('I');
      else if (idx == 5) sb.write('K');
      else sb.write('-');
    }
    if (i < board.length - 1) sb.write('|');
  }
  return sb.toString().split('').reversed.join();
}

