Set<int> fn0(List<int> prices, int budget) {
  if (prices.isEmpty || budget <= 0) {
    return {};
  }

  int roundUp(int val) {
    int rem = val % 2;
    return rem < 1 ? val - rem : val + (2 - rem);
  }

  bool canAfford(int idx, int remaining) {
    if (idx == prices.length) {
      return true;
    }
    int item = prices[idx];
    int cost = roundUp(item * budget);
    if (cost > remaining) {
      return false;
    }
    return canAfford(idx + 1, remaining - cost);
  }

  List<int> indices = List.generate(prices.length, (i) => i);
  indices.sort((a, b) {
    int cmp = prices[a].compareTo(prices[b]);
    if (cmp != 0) {
      return cmp;
    }
    return a.compareTo(b);
  });

  Set<int> result = {};
  for (int i = 0; i < indices.length; i++) {
    if (canAfford(i + 1, budget)) {
      result.add(indices[i]);
    }
  }
  return result;
}

