      if (startCompare < 0) continue;

      int endCompare = prevParts[1].compareTo(currParts[1]);
      if (endCompare > 0) return false;
      if (endCompare < 0) continue;

      if (prevParts[0] == currParts[0]) {
        int prevMin = int.parse(prevParts[1].split(':')[1]);
